begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_b2b_organizations(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('ORG-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),organization_code text unique not null default ('B2B-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),legal_name text not null,display_name text not null,vertical text not null check(vertical in('establishment','hospitality','health_partner','corporate')),organization_type text not null,registration_number text,territory_id uuid,tenant_id uuid references public.angelcare_marketplace_partner_tenants(id),crm_account_id uuid references public.angelcare_marketplace_crm_accounts(id),owner_id uuid,lifecycle_status text not null default 'prospect' check(lifecycle_status in('prospect','diagnostic','qualified','proposal','contracting','partner','active','paused','inactive','archived')),risk_level text not null default 'normal' check(risk_level in('low','normal','high','critical')),next_action text,next_action_at timestamptz,health_status text not null default 'unknown' check(health_status in('healthy','attention','at_risk','critical','unknown')),metadata jsonb not null default '{}',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_organization_sites(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,site_code text not null,name text not null,city text,address text,capacity int,active boolean not null default true,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,site_code));
create table if not exists public.angelcare_marketplace_b2b_contacts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,full_name text not null,job_title text,email text,phone text,decision_role text,primary_contact boolean not null default false,consent_status text not null default 'unknown',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_public_requests(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('B2BR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),vertical text not null check(vertical in('establishment','hospitality','health_partner','corporate')),organization_name text not null,city text not null,email text not null,phone text not null,capacity int,urgency text not null default 'exploration',needs text not null,source_locale text not null default 'fr' check(source_locale in('fr','en','ar')),consent_recorded_at timestamptz not null,status text not null default 'submitted' check(status in('submitted','triaged','qualified','converted','rejected','archived')),crm_lead_id uuid references public.angelcare_marketplace_crm_leads(id),owner_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_diagnostics(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('DIAG-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),vertical text not null check(vertical in('establishment','hospitality','health_partner','corporate')),diagnostic_type text not null,status text not null default 'draft' check(status in('draft','in_progress','submitted','under_review','clarification_required','qualified','not_qualified','converted','archived')),completion_score int not null default 0 check(completion_score between 0 and 100),qualification_score int check(qualification_score between 0 and 100),risk_level text not null default 'normal' check(risk_level in('low','normal','high','critical')),territory_id uuid,tenant_id uuid,owner_id uuid,reviewer_id uuid,submitted_at timestamptz,reviewed_at timestamptz,recommendation_summary text,next_action text,answers jsonb not null default '{}',source_locale text not null default 'fr' check(source_locale='fr'),version int not null default 1,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_diagnostic_sections(id uuid primary key default gen_random_uuid(),diagnostic_id uuid not null references public.angelcare_marketplace_b2b_diagnostics(id) on delete cascade,section_key text not null,title_fr text not null,weight numeric(8,3) not null default 1,completion_score int not null default 0,status text not null default 'not_started' check(status in('not_started','in_progress','completed','review_required')),sort_order int not null default 0,unique(diagnostic_id,section_key));
create table if not exists public.angelcare_marketplace_b2b_diagnostic_answers(id uuid primary key default gen_random_uuid(),diagnostic_id uuid not null references public.angelcare_marketplace_b2b_diagnostics(id) on delete cascade,section_key text not null,question_key text not null,answer_value jsonb not null,source_locale text not null default 'fr',answered_by uuid,answered_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(diagnostic_id,question_key));
create table if not exists public.angelcare_marketplace_b2b_recommendations(id uuid primary key default gen_random_uuid(),diagnostic_id uuid not null references public.angelcare_marketplace_b2b_diagnostics(id) on delete cascade,recommendation_type text not null,title_fr text not null,rationale_fr text not null,priority text not null default 'normal' check(priority in('low','normal','high','critical')),related_module_key text,estimated_value numeric(16,2),currency_label text not null default 'Dh',status text not null default 'draft' check(status in('draft','review','approved','included','rejected','archived')),owner_id uuid,reviewer_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_program_requests(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('PREQ-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),diagnostic_id uuid references public.angelcare_marketplace_b2b_diagnostics(id),vertical text not null,status text not null default 'draft' check(status in('draft','submitted','qualified','proposal_preparation','proposal_sent','negotiation','approved','rejected','contracting','activation','cancelled')),requested_scope jsonb not null default '{}',budget_min numeric(16,2),budget_max numeric(16,2),currency_label text not null default 'Dh',target_launch_at date,territory_id uuid,tenant_id uuid,owner_id uuid,next_action text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_programs(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('PROG-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),request_id uuid references public.angelcare_marketplace_b2b_program_requests(id),vertical text not null check(vertical in('establishment','hospitality','health_partner','corporate')),program_type text not null,name text not null,status text not null default 'configuration' check(status in('configuration','readiness_review','approved','scheduled','active','paused','completed','suspended','archived')),territory_id uuid,tenant_id uuid,starts_at timestamptz,ends_at timestamptz,capacity int,owner_id uuid,readiness_score int not null default 0 check(readiness_score between 0 and 100),risk_level text not null default 'normal' check(risk_level in('low','normal','high','critical')),next_action text,configuration jsonb not null default '{}',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_program_sites(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.angelcare_marketplace_b2b_programs(id) on delete cascade,site_id uuid not null references public.angelcare_marketplace_b2b_organization_sites(id),status text not null default 'configured',capacity int,schedule jsonb not null default '{}',unique(program_id,site_id));
create table if not exists public.angelcare_marketplace_b2b_program_services(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.angelcare_marketplace_b2b_programs(id) on delete cascade,catalog_item_id uuid references public.angelcare_marketplace_catalog_items(id),service_key text not null,name_fr text not null,configuration jsonb not null default '{}',status text not null default 'configured',unique(program_id,service_key));
create table if not exists public.angelcare_marketplace_b2b_readiness_checks(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.angelcare_marketplace_b2b_programs(id) on delete cascade,gate_key text not null,title_fr text not null,category text not null,required boolean not null default true,blocking boolean not null default true,status text not null default 'not_started' check(status in('not_started','in_progress','submitted','passed','failed','waived','not_applicable')),owner_id uuid,reviewer_id uuid,due_at timestamptz,evidence jsonb not null default '{}',blocker_reason text,sort_order int not null default 0,validated_at timestamptz,unique(program_id,gate_key));
create table if not exists public.angelcare_marketplace_b2b_program_approvals(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.angelcare_marketplace_b2b_programs(id) on delete cascade,approval_type text not null,status text not null default 'pending' check(status in('pending','approved','rejected','cancelled')),requested_by uuid,reviewer_id uuid,decision_reason text,decided_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_reports(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),program_id uuid references public.angelcare_marketplace_b2b_programs(id),report_type text not null,period_start date,period_end date,status text not null default 'draft' check(status in('draft','review','approved','published','archived')),metrics jsonb not null default '{}',evidence jsonb not null default '{}',published_at timestamptz,published_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_b2b_conversions(id uuid primary key default gen_random_uuid(),diagnostic_id uuid not null references public.angelcare_marketplace_b2b_diagnostics(id),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),conversion_type text not null check(conversion_type in('crm_opportunity','partner_tenant','both')),status text not null default 'pending' check(status in('pending','processing','completed','failed','rolled_back')),territory_id uuid,tenant_id uuid,crm_account_id uuid,crm_opportunity_id uuid,partner_tenant_id uuid,result jsonb not null default '{}',created_by uuid,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.angelcare_marketplace_establishment_profiles(organization_id uuid primary key references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,establishment_kind text not null check(establishment_kind in('school','creche','preschool','school_group')),enrolled_children int,classrooms int,licensed_capacity int,digital_maturity text not null default 'unknown',parent_communication_maturity text not null default 'unknown',safeguarding_maturity text not null default 'unknown',attendance_maturity text not null default 'unknown',billing_maturity text not null default 'unknown',transport_scope jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_establishment_academy_needs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,diagnostic_id uuid references public.angelcare_marketplace_b2b_diagnostics(id),need_key text not null,title_fr text not null,target_roles text[] not null default '{}',priority text not null default 'normal',estimated_learners int,status text not null default 'identified',recommended_training_keys text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_establishment_quality_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),request_type text not null default 'quality_check_360',status text not null default 'requested' check(status in('requested','qualified','scheduled','in_progress','review','completed','cancelled')),scope jsonb not null default '{}',scheduled_at timestamptz,score int check(score between 0 and 100),critical_findings int not null default 0,corrective_actions int not null default 0,owner_id uuid,reviewer_id uuid,report_id uuid references public.angelcare_marketplace_b2b_reports(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.angelcare_marketplace_create_b2b_diagnostic(p_payload jsonb,p_actor_id uuid,p_territory_id uuid,p_tenant_id uuid) returns public.angelcare_marketplace_b2b_diagnostics language plpgsql security definer set search_path=public as $$declare org public.angelcare_marketplace_b2b_organizations;diag public.angelcare_marketplace_b2b_diagnostics;v text;begin v:=coalesce(nullif(p_payload->>'vertical',''),'establishment');if v not in('establishment','hospitality','health_partner','corporate') then raise exception 'Invalid B2B vertical';end if;if nullif(p_payload->>'organization_id','') is not null then select * into org from public.angelcare_marketplace_b2b_organizations where id=(p_payload->>'organization_id')::uuid;else insert into public.angelcare_marketplace_b2b_organizations(legal_name,display_name,vertical,organization_type,territory_id,tenant_id,owner_id,lifecycle_status,next_action,created_by,updated_by) values(coalesce(nullif(p_payload->>'legal_name',''),p_payload->>'organization_name'),coalesce(nullif(p_payload->>'display_name',''),p_payload->>'organization_name'),v,coalesce(nullif(p_payload->>'organization_type',''),v),p_territory_id,p_tenant_id,p_actor_id,'diagnostic','Compléter le diagnostic',p_actor_id,p_actor_id) returning * into org;end if;if org.id is null then raise exception 'Organization not found';end if;insert into public.angelcare_marketplace_b2b_diagnostics(organization_id,vertical,diagnostic_type,status,territory_id,tenant_id,owner_id,answers,created_by,updated_by) values(org.id,v,coalesce(nullif(p_payload->>'diagnostic_type',''),v||'_diagnostic'),'in_progress',coalesce(p_territory_id,org.territory_id),coalesce(p_tenant_id,org.tenant_id),p_actor_id,coalesce(p_payload->'answers','{}'::jsonb),p_actor_id,p_actor_id) returning * into diag;insert into public.angelcare_marketplace_b2b_diagnostic_sections(diagnostic_id,section_key,title_fr,weight,sort_order) values(diag.id,'identity','Identité & périmètre',1,10),(diag.id,'operations','Opérations & capacité',1.5,20),(diag.id,'quality','Qualité & sécurité',2,30),(diag.id,'digital','Maturité digitale',1,40),(diag.id,'commercial','Budget & décision',1,50);return diag;end$$;
create or replace function public.angelcare_marketplace_transition_b2b_diagnostic(p_diagnostic_id uuid,p_target_status text,p_reason text,p_actor_id uuid) returns public.angelcare_marketplace_b2b_diagnostics language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_b2b_diagnostics;begin update public.angelcare_marketplace_b2b_diagnostics set status=p_target_status,reviewed_at=case when p_target_status in('qualified','not_qualified') then now() else reviewed_at end,submitted_at=case when p_target_status='submitted' then now() else submitted_at end,next_action=coalesce(nullif(p_reason,''),next_action),updated_by=p_actor_id,updated_at=now(),version=version+1 where id=p_diagnostic_id returning * into r;if r.id is null then raise exception 'Diagnostic not found';end if;return r;end$$;
create or replace function public.angelcare_marketplace_convert_b2b_diagnostic(p_diagnostic_id uuid,p_conversion_type text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare d public.angelcare_marketplace_b2b_diagnostics;o public.angelcare_marketplace_b2b_organizations;a public.angelcare_marketplace_crm_accounts;opp public.angelcare_marketplace_crm_opportunities;t public.angelcare_marketplace_partner_tenants;c public.angelcare_marketplace_b2b_conversions;begin select * into d from public.angelcare_marketplace_b2b_diagnostics where id=p_diagnostic_id for update;if d.status<>'qualified' then raise exception 'Diagnostic must be qualified';end if;select * into o from public.angelcare_marketplace_b2b_organizations where id=d.organization_id;insert into public.angelcare_marketplace_b2b_conversions(diagnostic_id,organization_id,conversion_type,status,territory_id,tenant_id,created_by) values(d.id,o.id,p_conversion_type,'processing',o.territory_id,o.tenant_id,p_actor_id) returning * into c;if p_conversion_type in('crm_opportunity','both') then if o.crm_account_id is null then insert into public.angelcare_marketplace_crm_accounts(account_type,legal_name,display_name,territory_id,status,owner_id,metadata,created_by,updated_by) values(o.organization_type,o.legal_name,o.display_name,o.territory_id,'qualified',o.owner_id,jsonb_build_object('b2b_organization_id',o.id),p_actor_id,p_actor_id) returning * into a;update public.angelcare_marketplace_b2b_organizations set crm_account_id=a.id,updated_at=now() where id=o.id;else select * into a from public.angelcare_marketplace_crm_accounts where id=o.crm_account_id;end if;insert into public.angelcare_marketplace_crm_opportunities(account_id,name,stage,estimated_value,currency_label,probability,owner_id,territory_id,next_action,created_by,updated_by) values(a.id,'Programme '||o.display_name,'qualified',(select coalesce(sum(estimated_value),0) from public.angelcare_marketplace_b2b_recommendations where diagnostic_id=d.id),'Dh',35,o.owner_id,o.territory_id,'Préparer la proposition B2B',p_actor_id,p_actor_id) returning * into opp;end if;if p_conversion_type in('partner_tenant','both') then if o.tenant_id is null then insert into public.angelcare_marketplace_partner_tenants(tenant_code,legal_name,display_name,tenant_type,territory_id,status,owner_id,created_by,updated_by) values('TEN-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)),o.legal_name,o.display_name,o.vertical,o.territory_id,'onboarding',o.owner_id,p_actor_id,p_actor_id) returning * into t;update public.angelcare_marketplace_b2b_organizations set tenant_id=t.id,updated_at=now() where id=o.id;else select * into t from public.angelcare_marketplace_partner_tenants where id=o.tenant_id;end if;end if;update public.angelcare_marketplace_b2b_diagnostics set status='converted',updated_by=p_actor_id,updated_at=now() where id=d.id;update public.angelcare_marketplace_b2b_conversions set status='completed',crm_account_id=a.id,crm_opportunity_id=opp.id,partner_tenant_id=t.id,result=jsonb_build_object('crm_account_id',a.id,'crm_opportunity_id',opp.id,'partner_tenant_id',t.id),completed_at=now() where id=c.id;return jsonb_build_object('conversion_id',c.id,'organization_id',o.id,'crm_account_id',a.id,'crm_opportunity_id',opp.id,'partner_tenant_id',t.id);end$$;
create or replace function public.angelcare_marketplace_transition_b2b_program(p_program_id uuid,p_target_status text,p_reason text,p_actor_id uuid) returns public.angelcare_marketplace_b2b_programs language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_b2b_programs;begin update public.angelcare_marketplace_b2b_programs set status=p_target_status,next_action=coalesce(nullif(p_reason,''),next_action),updated_by=p_actor_id,updated_at=now() where id=p_program_id returning * into r;if r.id is null then raise exception 'Program not found';end if;return r;end$$;
create index if not exists angelcare_b2b_org_scope_idx on public.angelcare_marketplace_b2b_organizations(territory_id,tenant_id,vertical,lifecycle_status,updated_at desc);create index if not exists angelcare_b2b_diag_scope_idx on public.angelcare_marketplace_b2b_diagnostics(territory_id,tenant_id,vertical,status,updated_at desc);create index if not exists angelcare_b2b_program_scope_idx on public.angelcare_marketplace_b2b_programs(territory_id,tenant_id,vertical,status,updated_at desc);
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.b2b.view','Voir B2B Vertical Command','B2B Vertical Universe',false),('marketplace.b2b.create','Créer une organisation B2B','B2B Vertical Universe',true),('marketplace.b2b.manage','Gérer le portefeuille B2B','B2B Vertical Universe',true),('marketplace.b2b.export','Exporter le portefeuille B2B','B2B Vertical Universe',true),('marketplace.b2b.organizations.merge','Fusionner des organisations','B2B Vertical Universe',true),('marketplace.b2b.organizations.assign','Affecter les propriétaires','B2B Vertical Universe',true),('marketplace.b2b.diagnostics.view','Voir les diagnostics','B2B Vertical Universe',false),('marketplace.b2b.diagnostics.manage','Gérer les diagnostics','B2B Vertical Universe',true),('marketplace.b2b.diagnostics.review','Réviser les diagnostics','B2B Vertical Universe',true),('marketplace.b2b.diagnostics.qualify','Qualifier les diagnostics','B2B Vertical Universe',true),('marketplace.b2b.programs.view','Voir les programmes','B2B Vertical Universe',false),('marketplace.b2b.programs.manage','Gérer les programmes','B2B Vertical Universe',true),('marketplace.b2b.programs.approve','Approuver les programmes','B2B Vertical Universe',true),('marketplace.b2b.programs.activate','Activer les programmes','B2B Vertical Universe',true),('marketplace.b2b.programs.pause','Suspendre les programmes','B2B Vertical Universe',true),('marketplace.b2b.establishments.view','Voir écoles et crèches','B2B Establishments',false),('marketplace.b2b.establishments.manage','Gérer écoles et crèches','B2B Establishments',true),('marketplace.b2b.establishments.quality_review','Réviser Quality Check 360','B2B Establishments',true),('marketplace.b2b.conversions.manage','Gérer les conversions CRM et tenant','B2B Vertical Universe',true),('marketplace.b2b.readiness.review','Réviser la readiness B2B','B2B Vertical Universe',true),('marketplace.b2b.reports.view','Voir les rapports B2B','B2B Vertical Universe',false)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.b2b.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/verticals/establishments',required_permissions=array['marketplace.b2b.establishments.view']::text[],version=version+1,updated_at=now() where introduced_by_mega_zip=12;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.b2b.establishments.enabled','Établissements, écoles & crèches','Diagnostic, Academy, Quality Check 360 et conversion tenant.',true,'active','Ultra Delivery 3/5 · Original MZ12') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
